P3 = "Perhatikan kata penghubung (でも・だから・それから) untuk menangkap alur."
J = 'tan'; JN = 'Teks pendek (短文)'
C = 'chu'; CN = 'Teks menengah (中文)'
def T(jp, idt, q, opts, ans, alasan, bukti, wrong, poin=P1):
    return dict(slot=J, jenis=JN, jp=jp, id=idt, qs=[(q, opts, ans, alasan, bukti, wrong, poin)])
def Cc(jp, idt, qs): return dict(slot=C, jenis=CN, jp=jp, id=idt, qs=qs)
